test_that("modular pipeline matches `setup_default_parameters()`", {
  fleet1_name <- "fleet1"

  fleet1_selectivity_defaults <- setup_default_Selectivity(
    data = data,
    fleet = fleet1_name
  )

  fleet1_fleet_defaults <- setup_default_Fleet(
    data = data,
    fleet = fleet1_name
  )

  survey1_name <- "survey1"

  survey1_selectivity_defaults <- setup_default_Selectivity(
    data = data,
    fleet = survey1_name
  )

  survey1_fleet_defaults <- setup_default_Fleet(
    data = data,
    fleet = survey1_name
  )

  recruitment_defaults <- setup_default_Recruitment(data = data)
  maturity_defaults <- setup_default_Maturity(data = data)
  growth_defaults <- setup_default_Growth()

  log_M <- log(0.2)
  log_rzero <- recruitment_defaults |>
    dplyr::filter(.data[["label"]] == "log_rzero") |>
    dplyr::pull(.data[["value"]])
  population_defaults <- setup_default_Population(
    data = data,
    log_M = log_M,
    log_init_naa = FIMS:::setup_default_log_init_naa(
      n_ages = get_n_ages(data),
      log_rzero = log_rzero,
      log_M = log_M
    )
  )

  modular_result <- dplyr::bind_rows(
    fleet1_selectivity_defaults,
    fleet1_fleet_defaults,
    survey1_selectivity_defaults,
    survey1_fleet_defaults,
    recruitment_defaults,
    maturity_defaults,
    growth_defaults,
    population_defaults
  )

  expected_result <- setup_default_parameters(data = data)

  #' @description Test that the modular pipeline output is identical to `setup_default_parameters()`.
  expect_equal(
    modular_result |>
      dplyr::arrange(dplyr::across(dplyr::everything())),
    expected_result |>
      dplyr::arrange(dplyr::across(dplyr::everything()))
  )

  clear()
})

test_that("modular pipeline with `purrr` matches `setup_default_parameters()`", {
  model_data <- get_data(data)
  fleets <- model_data |>
    dplyr::pull(.data[["fleet"]]) |>
    na.omit() |>
    unique()

  fleet_defaults <- purrr::map(
    fleets,
    function(fleet_i) {
      setup_default_Fleet(data = data, fleet = fleet_i)
    }
  ) |>
    dplyr::bind_rows()

  selectivity_defaults <- purrr::map(
    fleets,
    function(fleet_i) {
      setup_default_Selectivity(data = data, fleet = fleet_i)
    }
  ) |>
    dplyr::bind_rows()

  recruitment_defaults <- setup_default_Recruitment(data = data)
  maturity_defaults <- setup_default_Maturity(data = data)
  growth_defaults <- setup_default_Growth()

  log_M <- log(0.2)
  log_rzero <- recruitment_defaults |>
    dplyr::filter(.data[["label"]] == "log_rzero") |>
    dplyr::pull(.data[["value"]])
  log_init_naa <- FIMS:::setup_default_log_init_naa(
    n_ages = get_n_ages(data),
    log_rzero = log_rzero,
    log_M = log_M
  )

  population_defaults <- setup_default_Population(
    data = data,
    log_M = log_M,
    log_init_naa = log_init_naa
  )

  # Explicitly update log_init_naa values to mirror downstream modular workflows.
  population_defaults <- population_defaults |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_init_naa",
        age = get_ages(data),
        value = log_init_naa
      ),
      by = c("label", "age")
    )

  modular_result <- dplyr::bind_rows(
    selectivity_defaults,
    fleet_defaults,
    recruitment_defaults,
    maturity_defaults,
    growth_defaults,
    population_defaults
  )

  expected_result <- setup_default_parameters(data = data)

  #' @description Test that the modular pipeline output is identical to `setup_default_parameters()`.
  expect_true(identical(modular_result, expected_result))
  expect_equal(modular_result, expected_result)

  clear()
})

## Edge handling ----
test_that("`setup_default_parameters()` works with edge cases", {
  recruitment_without_distribution <- setup_default_Recruitment(
    data = data,
    distribution = NA_character_
  )

  #' @description Test that `log_sd` is not created when distribution is not specified.
  log_sd_value <- recruitment_without_distribution |>
    dplyr::filter(.data[["label"]] == "log_sd") |>
    dplyr::pull(.data[["value"]])

  expect_equal(log_sd_value, numeric(0))

  #' @description Test that `log_devs` estimation_type is constant when distribution is not specified.
  log_devs_value <- recruitment_without_distribution |>
    dplyr::filter(.data[["label"]] == "log_devs") |>
    dplyr::pull(.data[["estimation_type"]]) |>
    unique()

  expect_equal(log_devs_value, "constant")

  #' @description Test that `log_devs` distribution_type is `NA` when distribution is not specified.
  log_devs_distribution_type <- recruitment_without_distribution |>
    dplyr::filter(.data[["label"]] == "log_devs") |>
    dplyr::pull(.data[["distribution_type"]]) |>
    unique()

  expect_equal(log_devs_distribution_type, NA_character_)

  zero_catch_data <- data_big |>
    dplyr::mutate(
      observed = dplyr::if_else(type == "catch" & timing == 3, 0, observed)
    ) |>
    FIMSFrame()
  log_Fmort_defaults <- setup_default_Fleet(
    data = zero_catch_data,
    fleet = "fleet1"
  ) |>
    dplyr::filter(.data[["label"]] == "log_Fmort")
  #' @description Test that `log_Fmort` is fixed at -200 in a year with a catch of 0.
  expect_equal(
    dplyr::filter(log_Fmort_defaults, .data[["timing"]] == 3) |>
      dplyr::select("value", "estimation_type"),
    tibble::tibble(value = -200, estimation_type = "constant")
  )
  #' @description Test that `log_Fmort` stays estimated in years with catch.
  expect_equal(
    dplyr::filter(log_Fmort_defaults, .data[["timing"]] != 3) |>
      dplyr::pull(.data[["estimation_type"]]) |>
      unique(),
    "fixed_effects"
  )

  clear()
})

test_that("`setup_default_log_init_naa()` handles scalar and vector `log_M`", {
  n_ages <- get_n_ages(data)
  log_rzero <- log(1e+06)

  scalar_result <- FIMS:::setup_default_log_init_naa(
    n_ages = n_ages,
    log_rzero = log_rzero,
    log_M = log(0.2)
  )

  vector_log_M <- log(seq(0.15, 0.15 + (n_ages - 1) * 0.01, by = 0.01))
  vector_result <- FIMS:::setup_default_log_init_naa(
    n_ages = n_ages,
    log_rzero = log_rzero,
    log_M = vector_log_M
  )

  # One year of the unfished population dynamics: recruitment of R0 at age 0,
  # survival exp(-M) to the next age, and survivors of the last two ages
  # accumulating in the plus group.
  project_unfished_one_year <- function(numbers_at_age, m, rzero) {
    n <- length(numbers_at_age)
    projected <- c(rzero, numbers_at_age[-n] * exp(-m[-n]))
    projected[n] <- projected[n] + numbers_at_age[n] * exp(-m[n])
    projected
  }
  expected_m <- exp(vector_log_M)

  #' @description Test that scalar log_M still returns one value per age.
  expect_length(scalar_result, n_ages)
  #' @description Test that vector log_M gives the unfished equilibrium, i.e.,
  #' projecting one year returns the same numbers-at-age, including the plus group.
  expect_equal(
    project_unfished_one_year(exp(vector_result), expected_m, exp(log_rzero)),
    exp(vector_result)
  )
  #' @description Test the plus group against its known value for M = 0.2:
  #' R0 * exp(-0.2 * (n_ages - 1)) / (1 - exp(-0.2)).
  expect_equal(
    scalar_result[n_ages],
    log_rzero - 0.2 * (n_ages - 1) - log(1 - exp(-0.2))
  )

  clear()
})

test_that("`setup_default_log_init_naa()` keeps a finite plus group for small M", {
  n_ages <- get_n_ages(data)
  log_rzero <- log(1e+06)

  result <- FIMS:::setup_default_log_init_naa(
    n_ages = n_ages,
    log_rzero = log_rzero,
    log_M = -40
  )

  #' @description Test that a very small M gives a finite plus group of about R0 / M, where 1 - exp(-M) would round to 0.
  expect_equal(
    result[n_ages],
    log_rzero - (n_ages - 1) * exp(-40) + 40
  )

  clear()
})

## Error handling ----
test_that("`setup_default_parameters()` returns correct error messages", {
  #' @description Test that invalid `data` class triggers an informative error.
  expect_error(
    object = setup_default_parameters(data = "not_a_fimsframe"),
    regexp = "FIMSFrame"
  )

  clear()
})

test_that("`setup_default_log_init_naa()` returns correct error messages", {
  #' @description Test that invalid log_M length triggers an informative error.
  expect_error(
    object = FIMS:::setup_default_log_init_naa(
      n_ages = get_n_ages(data),
      log_rzero = log(1e+06),
      log_M = c(log(0.2), log(0.3))
    ),
    regexp = "log_M.*single numeric value.*length equal to n_ages"
  )

  clear()
})
